
/* ================= PROJECTS ================= */
const dOf=o=>new Date(2026,9,19+o);
const dl=o=>o===3?'Today':o===4?'Tomorrow':o===2?'Yesterday':dOf(o).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
const TST={todo:['To do','#7C818D'],prog:['In progress','#D98200'],review:['Review','#8A5CF2'],done:['Done','#2B63F6']};
const PRI={urgent:['Urgent','#E5482F'],high:['High','#F07C1A'],normal:['Normal','#2B63F6'],low:['Low','#8A8F9B']};
const PSTAT={'On track':'blue','At risk':'warn',Planning:'',Done:'blue'};
const PROJ={l2f:[
{id:'p1',n:'Harry Kaye quiz funnel',cl:'Harry Kaye PT',lead:'TR',st:'On track',pr:42,due:'28 Nov',c:'#EF5235',team:['TR','SN','AR','UM','BK'],fav:1,purpose:'Build a fitness quiz funnel that books discovery calls for Harry’s online coaching.'},
{id:'p2',n:'Mindful Money course launch',cl:'Mindful Money Co',lead:'AR',st:'At risk',pr:64,due:'14 Nov',c:'#6B4FF0',team:['AR','SN','BK'],fav:1,purpose:'Launch a $497 course with a webinar funnel and a 5-email sequence.'},
{id:'p3',n:'L2F website refresh',cl:'Internal',lead:'BK',st:'On track',pr:20,due:'20 Dec',c:'#2B5CF0',team:['BK','AR'],purpose:'Refresh layer2funnels.com with new case studies and a clearer offer.'},
{id:'p4',n:'Funnel Done Right Challenge',cl:'Internal',lead:'TR',st:'Planning',pr:8,due:'Jan 2027',c:'#F07C1A',team:['TR','UM'],purpose:'A 7-day beginner challenge with a companion book.'},
{id:'p5',n:'Apex Coaching webinar funnel',cl:'Apex Coaching',lead:'SN',st:'Done',pr:100,due:'Sep',c:'#13A592',team:['SN','BK'],arch:1,purpose:'Webinar funnel, launched in September.'},
{id:'p6',n:'Q3 ads test',cl:'Internal',lead:'UM',st:'Done',pr:100,due:'Sep',c:'#E9488F',team:['UM'],arch:1,purpose:'Test three ad angles for L2F lead magnet.'}],
aurj:[
{id:'a1',n:'Urdu Basics, Season 2',cl:'Internal',lead:'TR',st:'On track',pr:55,due:'30 Nov',c:'#B0305A',team:['TR','SN','AR'],fav:1,purpose:'Record and publish 12 lessons for Season 2.'},
{id:'a2',n:'Grade 9 Maths videos',cl:'Internal',lead:'UM',st:'At risk',pr:30,due:'15 Nov',c:'#0C7F95',team:['UM','BK'],purpose:'Short explainer videos for the Grade 9 syllabus.'},
{id:'a3',n:'Khushab classes, Term 2',cl:'Internal',lead:'TR',st:'Planning',pr:12,due:'Jan 2027',c:'#E8A33D',team:['TR'],purpose:'Plan the in-person term and worksheets.'},
{id:'a4',n:'Season 1 edits',cl:'Internal',lead:'AR',st:'Done',pr:100,due:'Aug',c:'#7E5BF2',team:['AR'],arch:1,purpose:'Final edits for Season 1.'}]};
const projs=()=>PROJ[org()];const proj=id=>projs().find(p=>p.id===id);
const mk=(n,st,as,o,pri,tags,sd,st2,s,len)=>({n,st,as,o,pri,tags,sd,stt:st2,s,len});
const TASKS={p1:[mk('Interview Harry about his clients','done','TR',0,'normal',['Research'],3,3,-10,6),mk('Customer avatar draft','review','UM',5,'high',['Strategy'],2,4,-4,8),mk('Quiz questions v2','prog','SN',3,'urgent',['Copy'],1,3,-2,6),mk('Quiz flow wireframe','prog','AR',4,'normal',['Design'],1,2,0,5),mk('Results page copy','todo','SN',8,'high',['Copy'],0,2,2,7),mk('Brand kit from client','done','AR',1,'normal',['Brand'],1,1,-6,5),mk('Lead magnet PDF','todo','AR',10,'normal',['Design'],0,0,5,6),mk('Build quiz in GoHighLevel','todo','BK',15,'normal',['Build'],0,5,10,8),mk('Email follow-up sequence','todo','SN',17,'low',['Copy'],0,4,12,6),mk('QA and launch checklist','todo','TR',23,'high',['Launch'],0,6,20,5)]};
['p2','p3','p4','p5','p6','a1','a2','a3','a4'].forEach((p,j)=>TASKS[p]=[['Kick-off and brief','done','TR',-2],['Outline and plan','prog','UM',3],['First draft','prog','SN',4],['Design pass','todo','AR',9],['Review with lead','review','TR',6],['Publish and check','todo','BK',16]].map(([n,st,as,o],i)=>mk(n,st,as,o+j%3,['high','normal','urgent','normal','low','normal'][i],[['Plan','Copy','Design','Review','Build'][i%5]],i%2,2,o-4+j%3,5+i%3)));
const tasksOf=pid=>TASKS[pid].map((t,i)=>Object.assign(t,{pid,i,id:pid+'-'+i}));
const allTasks=()=>projs().flatMap(p=>tasksOf(p.id));
const stPill=s=>`<span class="st" style="--c:${TST[s][1]}">${TST[s][0]}</span>`;
const priL=p=>`<span class="pri" style="--c:${PRI[p][1]}">${ic('flag',15)}${PRI[p][0]}</span>`;
const PNAV=()=>[['projects/home','Home','home'],['projects/mywork','My Work','mywork',allTasks().filter(t=>t.as==='TR'&&t.st!=='done').length,null,'My Work'],['projects/list','Projects','projects'],['projects/docs','Docs','doc'],['projects/boards','Whiteboards','whiteboard'],['projects/dash','Dashboards','dash'],['projects/ai','AI Assist','agents'],['projects/apps','App Center','plug']];
function pShell(cur,body,crumbs,o={}){const live=projs().filter(p=>!p.arch);
const side=`<div class="side-sec" style="display:flex;align-items:center">Projects<button class="iconbtn" style="margin-left:auto;width:36px;height:36px" data-act="newproj" aria-label="New project">${ic('plus',18)}</button></div><div class="side-list">${live.map(p=>`<button data-act="nav:projects/p/${p.id}/list" ${RT.p[1]===p.id?'aria-current="page"':''}><span class="pdot" style="--c:${p.c}"></span><span>${p.n}</span>${p.fav?`<i style="margin-left:auto;color:#E6A700">${ic('star',14).replace('fill="none"','fill="currentColor"')}</i>`:''}</button>`).join('')}</div><p class="hint" style="padding:8px 12px 0;font-size:12.5px">Archived projects live in search.</p>`;
return shell('projects',{nav:PNAV(),cur,body,crumbs:crumbs||[['Projects']],sideMid:side,search:'cmdk',searchLabel:'Search projects, tasks, docs',...o})}
const taskRow=t=>`<div class="trow"><button class="cbx" role="checkbox" aria-checked="${t.st==='done'}" aria-label="Mark ${t.n} done" data-act="tdone:${t.id}"><i style="${t.st==='done'?'background:var(--action);border-color:var(--action)':''}">${t.st==='done'?ic('check',14,'',3).replace('class="ic ','style="opacity:1;transform:none;color:var(--action-ink)" class="ic '):''}</i></button><button class="tname" data-act="task:${t.id}"><span>${t.n}</span>${t.stt?`<span class="sub">${ic('check',12,'',2.4)}${t.sd}/${t.stt}</span>`:''}</button><span class="hm">${av(t.as)}</span><span style="font-size:13px;color:${t.o<3&&t.st!=='done'?'var(--danger)':t.o<=4?'var(--warn)':'var(--text2)'};font-weight:${t.o<=4?600:400}">${dl(t.o)}</span><span class="hm">${priL(t.pri)}</span><button class="iconbtn hm" style="width:36px;height:36px" data-act="task:${t.id}" aria-label="Open ${t.n}">${ic('right',16)}</button></div>`;
VIEWS.projects=p=>{const pg=p[0]||'home';
if(pg==='p')return projectView(p[1],p[2]||'list');
if(pg==='home'){const my=allTasks().filter(t=>t.as==='TR'&&t.st!=='done').sort((a,b)=>a.o-b.o);const lead=projs().filter(x=>!x.arch);
return pShell('projects/home',`${head(`Good ${tod()==='morning'?'morning':tod()==='afternoon'?'afternoon':'evening'}, Tabish`,`${my.filter(t=>t.o<=4).length} tasks due by tomorrow across ${new Set(my.map(t=>t.pid)).size} projects.`,`<button class="btn ghost" data-act="cmdk">${ic('search',18)}Search</button><button class="btn primary" data-act="newproj">${ic('plus',18,'',2.2)}New project</button>`)}
<div class="split"><section class="panel"><div class="sec-h"><h2>Your priorities</h2><span class="n">${my.length}</span><button class="linkbtn" data-act="nav:projects/mywork">My Work</button></div><div class="tasklist" style="padding:0 8px 8px">${my.slice(0,6).map(taskRow).join('')}</div></section>
<div class="stackcol"><section class="panel"><div class="sec-h"><h2>Projects</h2></div><div style="padding:0 10px 12px;display:grid;gap:4px">${lead.map(x=>`<button class="linkrow" data-act="nav:projects/p/${x.id}/overview"><span class="pdot" style="--c:${x.c}"></span><span class="main"><b>${x.n}</b><span class="prog" style="margin-top:6px;--v:${x.pr}%"><i></i></span></span><span class="pill ${PSTAT[x.st]}">${x.st}</span></button>`).join('')}</div></section>
<section class="panel"><div class="sec-h"><h2>Recent updates</h2></div><ul class="feed">${[['SN','moved <b>Quiz questions v2</b> to In progress','10 min ago'],['UM','asked for review on <b>Customer avatar draft</b>','1 h ago'],['AR','attached <b>Quiz flow v1.fig</b>','Yesterday']].map(([a,t,w])=>`<li>${av(a)}<div><b>${PEOPLE[a][0].split(' ')[0]}</b> ${t}<small>${w}</small></div></li>`).join('')}</ul></section></div></div>`)}
if(pg==='mywork'){const my=allTasks().filter(t=>t.as==='TR');const G=[['Overdue',t=>t.o<3&&t.st!=='done'],['Today',t=>t.o===3&&t.st!=='done'],['This week',t=>t.o>3&&t.o<=9&&t.st!=='done'],['Later',t=>t.o>9&&t.st!=='done'],['Done',t=>t.st==='done']];
return pShell('projects/mywork',`${head('My Work','Everything assigned to you, across every project you can open.')}${G.map(([l,f])=>{const r=my.filter(f);return r.length?`<section class="panel" style="margin-bottom:16px"><div class="sec-h"><h2>${l}</h2><span class="n">${r.length}</span></div><div class="tasklist" style="padding:0 8px 8px">${r.map(t=>taskRow(t).replace('<button class="tname"',`<button class="tname"`).replace('</span>'+(t.stt?'':''),'</span>')+`<div style="padding:0 0 8px 50px;margin-top:-10px;font-size:12.5px;color:var(--muted)"><span class="pdot" style="--c:${proj(t.pid).c};display:inline-block;width:8px;height:8px;margin-right:6px"></span>${proj(t.pid).n}</div>`).join('')}</div></section>`:''}).join('')}`,[['My Work']])}
if(pg==='list'){const live=projs().filter(x=>!x.arch);return pShell('projects/list',`${head('Projects',`${live.length} active projects in ${oname()}.`,`<button class="btn primary" data-act="newproj">${ic('plus',18,'',2.2)}New project</button>`)}
<div class="toolbar"><label class="inp grow">${ic('search',18)}<input id="plfilter" placeholder="Filter active projects"></label><select class="sel" aria-label="Status"><option>All statuses</option><option>On track</option><option>At risk</option><option>Planning</option></select><select class="sel" aria-label="Client"><option>All clients</option><option>Internal</option></select></div>
<div class="tblwrap"><table class="tbl" id="ptable"><thead><tr><th>Project</th><th>Status</th><th>Lead</th><th>Team</th><th style="width:160px">Progress</th><th>Due</th></tr></thead><tbody>${live.map(x=>`<tr data-n="${x.n.toLowerCase()} ${x.cl.toLowerCase()}"><td class="t1"><button class="fname" data-act="nav:projects/p/${x.id}/overview"><span class="pdot" style="--c:${x.c}"></span><span>${x.n}<small>${x.cl}</small></span></button></td><td data-l="Status"><span class="pill ${PSTAT[x.st]}">${x.st}</span></td><td data-l="Lead">${av(x.lead)}</td><td data-l="Team">${avs(x.team.slice(0,4))}</td><td data-l="Progress"><span style="display:flex;align-items:center;gap:8px;min-width:120px"><span class="prog" style="flex:1;--v:${x.pr}%"><i></i></span><span class="mono" style="font-size:12.5px">${x.pr}%</span></span></td><td data-l="Due">${x.due}</td></tr>`).join('')}</tbody></table></div>
<button class="linkrow" style="margin-top:14px;border:1.5px dashed var(--line2)" data-act="cmdk:is:archived">${ic('archive')}<span class="main"><b>Looking for an archived project?</b><small>Archived projects are hidden everywhere except search. Search “is:archived”.</small></span>${ic('search',18)}</button>`)}
if(pg==='docs')return pShell('projects/docs',`${head('Docs','Documents that belong to projects. They stay with the project and are never copied to Drive.',`<button class="btn primary" data-act="toast:Pick a project first. New docs belong to one project.">${ic('plus',18,'',2.2)}New doc</button>`)}<div class="tblwrap"><table class="tbl"><thead><tr><th>Doc</th><th>Project</th><th>Owner</th><th>Updated</th></tr></thead><tbody>${projs().filter(x=>!x.arch).flatMap((x,i)=>[['Project brief',x],['Meeting notes, week '+(i+2),x]]).map(([n,x],i)=>`<tr><td class="t1"><button class="fname" data-act="nav:drive/edit/doc/brief"><span class="ft doc">DOC</span>${n}</button></td><td data-l="Project"><span style="display:inline-flex;gap:8px;align-items:center"><span class="pdot" style="--c:${x.c}"></span>${x.n}</span></td><td data-l="Owner">${av(x.lead)}</td><td data-l="Updated">${dl(3-i)}</td></tr>`).join('')}</tbody></table></div>`,[['Docs']]);
if(pg==='boards')return pShell('projects/boards',`${head('Whiteboards','Boards that belong to projects. Only project members can open them.')}<div class="cardgrid">${projs().filter(x=>!x.arch).map(x=>`<button class="card" data-act="nav:whiteboard/board/b1"><div class="thumb" data-t="image" style="border-radius:14px;background:radial-gradient(var(--line2) 1px,transparent 1px) 0 0/14px 14px,var(--surface2)"></div><h3>${x.n.split(',')[0]} board</h3><div class="foot"><span class="pdot" style="--c:${x.c}"></span>${x.n}</div></button>`).join('')}</div>`,[['Whiteboards']]);
if(pg==='dash'){const P=projs().filter(x=>!x.arch),T=allTasks();const od=T.filter(t=>t.o<3&&t.st!=='done');
return pShell('projects/dash',`${head('Dashboards','Progress, overdue work and workload across projects you can open.')}<div class="focus" style="margin-top:0">${[[P.length,'Active projects'],[T.filter(t=>t.st!=='done').length,'Open tasks'],[od.length,'Overdue'],['31h','Logged this week']].map(([b,s])=>`<div><b>${b}</b><span>${s}</span></div>`).join('')}</div>
<div class="grid2"><section class="panel" style="padding:4px 20px 18px"><div class="sec-h" style="padding-left:0"><h2>Progress by project</h2></div>${P.map(x=>`<div class="ws-bar"><span class="nm" style="width:180px"><span class="pdot" style="--c:${x.c}"></span><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${x.n}</span></span><span class="prog" style="--v:${x.pr}%"><i style="background:${x.c}"></i></span><span class="mono" style="width:40px;text-align:right;font-size:13px">${x.pr}%</span></div>`).join('')}</section>
<section class="panel" style="padding:4px 20px 18px"><div class="sec-h" style="padding-left:0"><h2>Workload this week</h2><span class="hint" style="margin-left:auto">For balancing, never for scoring.</span></div>${Object.keys(PEOPLE).map((k,i)=>{const h=[22,34,18,38,12][i];return `<div class="ws-bar"><span class="nm">${av(k)}${PEOPLE[k][0].split(' ')[0]}</span><span class="prog" style="--v:${h/40*100}%"><i style="${h>35?'background:var(--warn)':''}"></i></span><span class="mono" style="width:40px;text-align:right;font-size:13px">${h}h</span></div>`}).join('')}</section>
<section class="panel"><div class="sec-h"><h2>Overdue and blocked</h2><span class="n">${od.length}</span></div><div class="tasklist" style="padding:0 8px 8px">${od.map(taskRow).join('')||'<p class="hint" style="padding:12px">Nothing overdue.</p>'}</div></section>
<section class="panel" style="padding:4px 20px 18px"><div class="sec-h" style="padding-left:0"><h2>Time logged</h2></div><div style="display:flex;align-items:flex-end;gap:10px;height:170px;padding-top:10px">${[4,7,6,8,6,0,0].map((h,i)=>`<div style="flex:1;display:grid;justify-items:center;gap:6px"><span style="width:100%;height:${h*16+4}px;border-radius:8px 8px 4px 4px;background:${i===3?'var(--brand)':'var(--action)'};opacity:${h?1:.25}"></span><small class="muted">${'MTWTFSS'[i]}</small></div>`).join('')}</div></section></div>`,[['Dashboards']])}
if(pg==='ai')return pShell('projects/ai',`${head('AI Assist','Ready for when you switch it on. It drafts and summarizes; you approve every change.')}
<div class="notice plain" style="margin-bottom:18px">${ic('lock',20)}<span><b>Not connected yet.</b> Needs your approval of the AI provider, its cost and the data rules. Nothing here runs today.</span></div>
<div class="panel" style="padding:20px;margin-bottom:18px"><label class="inp" style="min-height:56px">${ic('agents',20)}<input aria-disabled="true" placeholder="Ask about any project you can open… e.g. “What’s blocking the Harry Kaye launch?”" readonly></label><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">${['Summarize this week','What’s overdue?','Draft a client update','Turn a brief into tasks'].map(s=>`<button class="chip" aria-disabled="true" data-act="toast:AI Assist turns on after approval.">${s}</button>`).join('')}</div></div>
<div class="cardgrid">${[['Summaries','Project, task and activity summaries with links back to sources.','doc'],['Brief to tasks','Turns an approved brief into a draft checklist. You confirm before anything is created.','mywork'],['Status drafts','Writes a progress update you can edit before saving.','msg'],['Gap finder','Points out missing owners, dates or blocked items.','search']].map(([t,d,i])=>`<div class="card"><span class="tic rv" style="width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--action-tint);color:var(--action)">${ic(i)}</span><h3>${t}</h3><p>${d}</p><div class="foot">${sp('Planned')}</div></div>`).join('')}</div>
<p class="hint" style="margin-top:18px">Guardrails built in: AI only sees what you can see, never changes status, assigns work or sends anything without your confirmation, and every action is logged.</p>`,[['AI Assist']]);
if(pg==='apps'){const L=[['Google Calendar','Calendar','#2B63F6','G','Show deadlines and milestones on your calendar.'],['Slack','Communication','#611F69','S','Send focused task notifications to a channel.'],['Microsoft Teams','Communication','#4B53BC','T','Post project updates to Teams.'],['GitHub','Development','#24292F','GH','Link issues, commits and pull requests to tasks.'],['Figma','Design','#E2553D','F','Attach designs to tasks with live previews.'],['Zoom','Meetings','#2D8CFF','Z','Add meeting links to tasks and milestones.'],['Google Drive','Cloud storage','#14A493','D','Reference files. Project docs stay in Projects.'],['Outlook','Calendar','#0F6CBD','O','Show deadlines in Outlook.']];
return pShell('projects/apps',`${head('App Center','Connect tools on purpose. Nothing is imported or synced unless you choose it.')}<div class="toolbar">${vsw([['all','All'],['on','Connected'],['off','Not connected']],'all','noop')}<label class="inp grow">${ic('search',18)}<input placeholder="Search apps"></label></div>
<div class="cardgrid">${L.map(([n,c,col,lg,d])=>`<div class="card"><div class="integ"><span class="lg" style="--c:${col}">${lg}</span><div><h3>${n}</h3><small class="muted">${c}</small></div></div><p>${d}</p><div class="foot"><span class="pill">Not connected</span><button class="btn ghost sm" style="margin-left:auto" aria-disabled="true" data-act="toast:Connections need the backend and an admin’s approval.">Connect</button></div></div>`).join('')}</div><p class="hint" style="margin-top:16px">Organization connections are managed by admins. Personal connections are labelled “Personal”. Each connection asks for the smallest access it needs.</p>`,[['App Center']])}
return pShell('projects/home','')};
function projectView(id,view){const x=proj(id);if(!x)return pShell('projects/list',emptyS(`<span style="font:800 64px/1 var(--font-d);color:var(--line2)">?</span>`,'We couldn’t find that','It may have moved, or you may not have access.',`<button class="btn ink" data-act="nav:projects/home">Go to Projects Home</button>`));
const T=tasksOf(id);const V=[['overview','Overview'],['list','List',T.length],['board','Board'],['calendar','Calendar'],['timeline','Timeline'],['docs','Docs'],['boards','Whiteboards'],['activity','Activity']];
let body='';
if(view==='overview'){const done=T.filter(t=>t.st==='done').length,od=T.filter(t=>t.o<3&&t.st!=='done').length;body=`<div class="split"><div class="stackcol"><section class="panel" style="padding:20px"><p class="over">Purpose</p><p style="font-size:17px;margin-top:8px">${x.purpose}</p><div class="focus" style="margin:18px 0 0;border-bottom:0">${[[T.length-done,'Open'],[done,'Done'],[od,'Overdue'],['14h','Logged']].map(([b,s])=>`<div><b style="font-size:32px">${b}</b><span>${s}</span></div>`).join('')}</div></section>
<section class="panel"><div class="sec-h"><h2>Latest status update</h2><button class="linkbtn" data-act="toast:Write an update. AI drafting turns on later.">Write update</button></div><div style="padding:0 20px 20px;display:grid;gap:10px"><div style="display:flex;gap:10px;align-items:center">${av(x.lead)}<b>${PEOPLE[x.lead][0]}</b><span class="pill ${PSTAT[x.st]}">${x.st}</span><small class="muted">Monday</small></div><p class="tx2">Copy is moving, design is one day behind. The client approved the strategy on 3 Oct. Next: quiz questions v2 to Harry by Friday.</p></div></section>
<section class="panel"><div class="sec-h"><h2>Milestones</h2></div><div class="rows">${[['Strategy approved','3 Oct',1],['Copy approved','24 Oct',0],['Build complete','14 Nov',0],['Launch',x.due,0]].map(([n,d,ok])=>`<div class="row" style="min-height:52px"><span class="tic ${ok?'rv':''}">${ic(ok?'check':'flag',18)}</span><div class="main"><b>${n}</b></div><span class="due">${d}</span></div>`).join('')}</div></section></div>
<div class="stackcol"><section class="panel" style="padding:18px 20px"><dl class="kv2"><dt>Client</dt><dd>${x.cl}</dd><dt>Lead</dt><dd style="display:flex;gap:8px;align-items:center">${av(x.lead)}${PEOPLE[x.lead][0]}</dd><dt>Dates</dt><dd>1 Oct to ${x.due}</dd><dt>Status</dt><dd><span class="pill ${PSTAT[x.st]}">${x.st}</span></dd><dt>Goal</dt><dd><button class="linkbtn" data-act="toast:Goals come from Planner, designed next round.">Link a Planner goal</button></dd></dl></section>
<section class="panel"><div class="sec-h"><h2>Team</h2><span class="n">${x.team.length}</span></div><div class="rows">${x.team.map(k=>`<div class="row" style="min-height:52px">${av(k)}<div class="main"><b>${PEOPLE[k][0]}</b><small>${PEOPLE[k][2]}${k===x.lead?' · Project lead':''}</small></div></div>`).join('')}</div></section></div></div>`}
if(view==='list'){body=['todo','prog','review','done'].map(s=>{const r=T.filter(t=>t.st===s);return `<section class="panel" style="margin-bottom:14px"><div class="grp-h">${stPill(s)}<span class="muted mono" style="font-size:12.5px">${r.length}</span></div><div class="tasklist" style="padding:0 8px"><div class="trow hd hm"><span></span><span>Name</span><span>Assignee</span><span>Due</span><span>Priority</span><span></span></div>${r.map(taskRow).join('')}</div>${x.arch?'':`<button class="addrow" data-act="addtask:${id}|${s}">${ic('plus',18)}Add task</button>`}</section>`}).join('')}
if(view==='board')body=`<div class="kanban">${['todo','prog','review','done'].map(s=>{const r=T.filter(t=>t.st===s);return `<div class="kcol" data-st="${s}"><div class="kcol-h">${stPill(s)}<span class="muted mono" style="font-size:12.5px">${r.length}</span><button class="iconbtn" style="margin-left:auto;width:36px;height:36px" data-act="addtask:${id}|${s}" aria-label="Add task">${ic('plus',18)}</button></div>${r.map(t=>`<button class="kcard" draggable="${!x.arch}" data-id="${t.id}" data-act="task:${t.id}"><span style="display:flex;gap:6px">${t.tags.map(g=>`<span class="tag">${g}</span>`).join('')}</span><b>${t.n}</b><span class="foot">${av(t.as)}<span style="color:${t.o<3&&t.st!=='done'?'var(--danger)':'inherit'}">${ic('cal',14)} ${dl(t.o)}</span>${t.stt?`<span style="margin-left:auto">${ic('check',13)} ${t.sd}/${t.stt}</span>`:''}</span></button>`).join('')}</div>`}).join('')}</div><p class="hint" style="margin-top:8px">Drag cards between columns. On a phone, tap a card to change its status.</p>`;
if(view==='calendar')body=`<div class="toolbar"><b style="font:700 20px/1 var(--font-d)">October 2026</b><span class="grow"></span><button class="iconbtn" aria-label="Previous month" data-act="noop">${ic('right',18).replace('<svg','<svg style="transform:scaleX(-1)"')}</button><button class="btn ghost sm" data-act="noop">Today</button><button class="iconbtn" aria-label="Next month" data-act="noop">${ic('right',18)}</button></div><div class="cal">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dh">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const o=i-21,d=dOf(o);return `<div class="dc ${d.getMonth()!==9?'out':''} ${o===3?'today':''}"><span class="dn">${d.getDate()}</span>${T.filter(t=>t.o===o).map(t=>`<button class="ev" style="--c:${TST[t.st][1]}" data-act="task:${t.id}">${t.n}</button>`).join('')}</div>`}).join('')}</div>`;
if(view==='timeline'){const L=o=>((o+14)/42*100).toFixed(2);body=`<div class="gantt"><div class="gantt-in"><div class="g-head"><span style="padding:10px 14px;font:600 11.5px/1 var(--font);color:var(--muted);letter-spacing:.06em;text-transform:uppercase">Task</span><div class="wk">${[-14,-7,0,7,14,21].map(o=>`<span>${dOf(o).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span>`).join('')}</div></div>${T.map(t=>`<div class="g-row"><span class="gn">${av(t.as)}${t.n}</span><div class="g-track"><button class="g-bar" style="left:${L(t.s)}%;width:${(t.len/42*100).toFixed(2)}%;--c:${TST[t.st][1]}" data-act="task:${t.id}">${t.n}</button></div></div>`).join('')}<div class="g-today" style="left:calc(240px + (100% - 240px) * ${(17/42).toFixed(3)})" title="Today"></div></div></div><p class="hint" style="margin-top:8px">Red line is today. Drag to reschedule comes with the backend.</p>`}
if(view==='docs')body=`<div class="toolbar"><span class="hint grow">Owned by this project. Not copied to Drive.</span><button class="btn primary" data-act="nav:drive/edit/doc/brief">${ic('plus',18,'',2.2)}New doc</button></div><div class="cardgrid">${['Project brief','Client interview notes','Quiz question bank','Launch checklist'].map((n,i)=>`<button class="card" data-act="nav:drive/edit/doc/brief"><div class="thumb" data-t="doc" style="border-radius:12px"></div><h3>${n}</h3><div class="foot">${av(x.team[i%x.team.length])}Updated ${dl(3-i)}</div></button>`).join('')}</div>`;
if(view==='boards')body=`<div class="cardgrid">${['Quiz flow map','Kick-off workshop'].map(n=>`<button class="card" data-act="nav:whiteboard/board/b1"><div class="thumb" style="border-radius:14px;background:radial-gradient(var(--line2) 1px,transparent 1px) 0 0/14px 14px,var(--surface2)"></div><h3>${n}</h3><div class="foot">Project board · members only</div></button>`).join('')}<button class="card" style="place-items:center;border-style:dashed;min-height:200px" data-act="nav:whiteboard/board/b1">${ic('plus',28)}<b>New board</b></button></div>`;
if(view==='activity')body=`<section class="panel" style="padding:20px;max-width:760px">${[['SN','moved <b>Quiz questions v2</b> to In progress','10 min ago'],['UM','requested review on <b>Customer avatar draft</b>','1 h ago'],['AR','completed <b>Brand kit from client</b>','Yesterday'],['TR','created this project','1 Oct']].map(([a,t,w])=>`<div class="comment">${av(a)}<div><p>${PEOPLE[a][0]} ${t}</p><small>${w}</small></div></div>`).join('')}<div class="compose" style="margin-top:14px"><textarea placeholder="Write a comment. Use @ to mention someone." aria-label="Comment"></textarea><button class="btn ink" data-act="toast:Comment posted.:ok">${ic('send',18)}</button></div></section>`;
const banner=x.arch?`<div class="notice plain" style="margin-bottom:16px">${ic('archive',20)}<span><b>Archived.</b> Read only. It’s hidden from the sidebar and lists, and only appears in search.</span><button class="btn ink sm" style="margin-left:auto" data-act="parch:${id}">Restore</button></div>`:'';
return pShell('',`${banner}<div class="ph"><span class="pbig" style="--c:${x.c}">${ic('projects',24,'',2)}</span><div><h1>${x.n}</h1><div class="meta"><span>${x.cl}</span>·<span style="display:inline-flex;gap:6px;align-items:center">${av(x.lead)}${PEOPLE[x.lead][0]}</span>·<span>Due ${x.due}</span><span class="pill ${PSTAT[x.st]}">${x.st}</span></div></div><div class="acts">${avs(x.team.slice(0,4))}<button class="btn ghost sm" data-act="toast:Sharing opens a dialog.">${ic('share',16)}Share</button><button class="iconbtn" aria-label="More actions" data-act="pmenu:${id}">${ic('more')}</button></div></div>
${tabs(V,view,`projects/p/${id}/`)}${body}`,[['Projects','projects/list'],[x.n]])}
function taskDrawer(id){const[pid,i]=id.split('-');const t=tasksOf(pid)[+i],x=proj(pid);
openDrawer(`<div class="drw-h"><span class="pdot" style="--c:${x.c}"></span><small class="muted grow">${x.n}</small><button class="iconbtn" data-act="toast:Link copied.:ok" aria-label="Copy link">${ic('link')}</button><button class="iconbtn" data-act="drawerx" aria-label="Close">${ic('x')}</button></div>
<input class="drw-title" value="${esc(t.n)}" aria-label="Task name">
<dl class="props"><dt>${ic('mywork',16)}Status</dt><dd><select class="sel" data-tst="${id}" aria-label="Status">${Object.entries(TST).map(([k,v])=>`<option value="${k}" ${k===t.st?'selected':''}>${v[0]}</option>`).join('')}</select></dd><dt>${ic('user',16)}Assignee</dt><dd>${av(t.as)}${PEOPLE[t.as][0]}</dd><dt>${ic('cal',16)}Dates</dt><dd>${dl(t.s)} → ${dl(t.o)}</dd><dt>${ic('flag',16)}Priority</dt><dd>${priL(t.pri)}</dd><dt>${ic('tag',16)}Tags</dt><dd>${t.tags.map(g=>`<span class="tag">${g}</span>`).join('')}<button class="linkbtn" style="font-size:13px" data-act="noop">+ Add</button></dd></dl>
<div class="sec-t">${ic('timer',16)}Time</div><div class="timer" id="tmr"><button class="btn ink sm" data-act="timer">${ic('play',16)}Start</button><b>00:00:00</b><small class="muted">Logged 2h 10m · <button class="linkbtn" style="font-size:13px;min-height:0" data-act="toast:Manual edits are for authorized roles.">Add time</button></small></div>
<div class="sec-t">Description</div><p class="tx2" contenteditable="true" style="padding:10px;border-radius:10px;border:1px solid var(--line)">Write ten quiz questions that sort visitors into three goals: lose fat, build muscle, feel fitter. Use Harry’s language from the interview.</p>
<div class="sec-t">${ic('check',16)}Subtasks <span class="muted mono">${t.sd}/${t.stt}</span><button class="linkbtn" data-act="toast:AI subtask drafts turn on after approval.">${ic('agents',14)} Suggest with AI</button></div><div class="checkl">${Array.from({length:t.stt||2},(_,j)=>`<div class="row ${j<t.sd?'done':''}"><button class="cbx" role="checkbox" aria-checked="${j<t.sd}" data-act="sub" aria-label="Toggle subtask"><i>${ic('check',14,'',3)}</i></button><div class="main"><b>${['Draft questions','Check against avatar','Send to Harry','Revise from notes','Final read','Hand to build'][j%6]}</b></div></div>`).join('')}</div>
<div class="sec-t">${ic('clip',16)}Attachments</div><div style="display:flex;gap:8px;flex-wrap:wrap"><span class="chip">${ic('doc',16)}Quiz brief</span><button class="chip" data-act="toast:Upload needs the backend.">${ic('upload',16)}Add file</button></div>
<div class="sec-t">${ic('msg',16)}Comments and activity</div><div class="comment">${av('UM')}<div class="bub">Harry prefers “get fit” over “lose weight”. Can we use that?<br><small>1 h ago</small></div></div><div class="comment">${av('SN')}<div class="bub">Yes, updating question 3 now.<br><small>40 min ago</small></div></div><p class="hint" style="margin:6px 0 12px">${ic('hist',14)} Sana changed status to In progress · Tuesday</p><div class="compose"><textarea placeholder="Comment" aria-label="Comment"></textarea><button class="btn ink" data-act="toast:Comment posted.:ok" aria-label="Send">${ic('send',18)}</button></div>`)}
/* smart search */
const CK={f:'all'};
function openCmdk(q=''){closeCmdk();const d=document.createElement('div');d.className='cmdk-scrim';d.innerHTML=`<div class="cmdk" role="dialog" aria-label="Search"><div class="cmdk-in">${ic('search',22)}<input id="ckq" placeholder="Search projects, tasks, docs… try “quiz”, “@me overdue”, “is:archived”" value="${esc(q)}" autocomplete="off"><kbd>Esc</kbd></div><div class="cmdk-chips">${[['all','All'],['proj','Projects'],['task','Tasks'],['doc','Docs'],['arch','Archived'],['me','Assigned to me'],['od','Overdue']].map(([k,l])=>`<button aria-pressed="${CK.f===k}" data-act="ckf:${k}">${l}</button>`).join('')}</div><div class="cmdk-res" id="ckr"></div><div class="cmdk-foot"><span><kbd>↑</kbd> <kbd>↓</kbd> move</span><span><kbd>Enter</kbd> open</span><span>Understands typos, clients, tags and people.</span></div></div>`;document.body.append(d);ckRun();setTimeout(()=>$('#ckq').focus(),20)}
function closeCmdk(){$('.cmdk-scrim')?.remove()}
const fz=(s,q)=>{s=s.toLowerCase();if(!q)return 1;const i=s.indexOf(q);if(i>=0)return 100-i;let j=0;for(const ch of s)if(ch===q[j])j++;if(j===q.length)return 40;let m=0;for(let k=0;k<q.length-1;k++)if(s.includes(q.slice(k,k+2)))m++;return m>=Math.max(2,q.length-3)?20:0};
const hl=(s,q)=>{const i=q?s.toLowerCase().indexOf(q):-1;return i<0?esc(s):esc(s.slice(0,i))+'<mark>'+esc(s.slice(i,i+q.length))+'</mark>'+esc(s.slice(i+q.length))};
function ckRun(){let raw=($('#ckq')?.value||'').toLowerCase();let f=CK.f;if(/is:archived/.test(raw)){f='arch';raw=raw.replace('is:archived','')}const me=/@me/.test(raw)||f==='me',od=/overdue/.test(raw)||f==='od';const q=raw.replace(/@me|overdue/g,'').trim();
const P=projs().map(p=>({p,s:Math.max(fz(p.n,q),fz(p.cl,q)*.8)})).filter(r=>r.s>0&&(f==='arch'?r.p.arch:true)&&!me&&!od&&['all','proj','arch'].includes(f)).sort((a,b)=>b.s-a.s);
const Tk=allTasks().map(t=>({t,s:Math.max(fz(t.n,q),fz(t.tags.join(' '),q)*.7,fz(proj(t.pid).n,q)*.5,fz(PEOPLE[t.as][0],q)*.6)})).filter(r=>r.s>0&&(!me||r.t.as==='TR')&&(!od||(r.t.o<3&&r.t.st!=='done'))&&['all','task','me','od'].includes(f)&&(q||me||od||f==='task')).sort((a,b)=>b.s-a.s);
const Dc=['Project brief','Quiz question bank','Launch checklist','Client interview notes'].map(n=>({n,s:fz(n,q)})).filter(r=>r.s>0&&q&&['all','doc'].includes(f));
const g=(t,a)=>a.length?`<h5>${t}</h5>${a.join('')}`:'';
const html=g(f==='arch'?'Archived projects':'Projects',P.slice(0,6).map(({p})=>`<button data-act="nav:projects/p/${p.id}/overview"><span class="pdot" style="--c:${p.c}"></span><span class="main"><b>${hl(p.n,q)}</b><small>${p.cl} · ${PEOPLE[p.lead][0]}</small></span>${p.arch?'<span class="pill">'+ic('archive',13)+'Archived</span>':`<span class="pill ${PSTAT[p.st]}">${p.st}</span>`}</button>`))
+g('Tasks',Tk.slice(0,7).map(({t})=>`<button data-act="cktask:${t.id}">${stPill(t.st).replace(TST[t.st][0],'')}<span class="main"><b>${hl(t.n,q)}</b><small>${proj(t.pid).n} · ${PEOPLE[t.as][0]} · ${dl(t.o)}</small></span>${proj(t.pid).arch?'<span class="pill">Archived</span>':''}</button>`))
+g('Docs',Dc.map(d=>`<button data-act="nav:drive/edit/doc/brief"><span class="ft doc">DOC</span><span class="main"><b>${hl(d.n,q)}</b><small>Project doc</small></span></button>`));
$('#ckr').innerHTML=(html||`<div class="empty" style="padding:30px">${ic('search',28)}<h3 style="font-size:18px">No matches for “${esc(q)}”</h3><p>Try fewer words, or a client or person’s name.</p></div>`)+`<div class="ai-row">${ic('agents',20)}<span style="flex:1">${q?`Ask AI about “${esc(q)}”`:'Ask AI across your projects'}</span><span class="pill">Coming later</span></div>`;
const b=$('#ckr button');if(b)b.setAttribute('aria-selected','true')}
INPUT.ckq=()=>ckRun();
INPUT.plfilter=e=>{const q=e.value.toLowerCase();$$('#ptable tbody tr').forEach(r=>r.hidden=!r.dataset.n.includes(q))};
document.addEventListener('keydown',e=>{if(!$('.cmdk-scrim'))return;const L=$$('#ckr button');let i=L.findIndex(b=>b.getAttribute('aria-selected')==='true');if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();L[i]?.removeAttribute('aria-selected');i=(i+(e.key==='ArrowDown'?1:-1)+L.length)%L.length;L[i]?.setAttribute('aria-selected','true');L[i]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&e.target.id==='ckq'){e.preventDefault();L[i]?.click()}});
let TMR=null;
Object.assign(ACT,{
cmdk:v=>openCmdk(v||''),ckf:v=>{CK.f=v;$$('.cmdk-chips button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.act==='ckf:'+v));ckRun()},
cktask:v=>{closeCmdk();taskDrawer(v)},task:v=>taskDrawer(v),
tdone:v=>{const[p,i]=v.split('-');const t=TASKS[p][+i];t.st=t.st==='done'?'todo':'done';if(t.st==='done')toast('Task done. Nice.','ok',1800);draw()},
addtask:v=>{const[p,s]=v.split('|');dlg({title:'Add task',body:`<div class="field" style="margin-top:12px"><label for="nt">Task name</label><input id="nt" placeholder="What needs doing?"></div><div class="row2"><div class="field"><label for="nta">Assignee</label><select id="nta">${Object.keys(PEOPLE).map(k=>`<option value="${k}">${PEOPLE[k][0]}</option>`).join('')}</select></div><div class="field"><label for="ntp">Priority</label><select id="ntp">${Object.keys(PRI).map(k=>`<option value="${k}" ${k==='normal'?'selected':''}>${PRI[k][0]}</option>`).join('')}</select></div></div>`,acts:[['Cancel','noop'],['Add task',`addtask2:${p}|${s}`,'primary']]});setTimeout(()=>$('#nt').focus(),40)},
addtask2:v=>{const[p,s]=v.split('|');const n=($('#nt')?.value||'').trim()||'New task';TASKS[p].push(mk(n,s,$('#nta').value,7,$('#ntp').value,['New'],0,0,4,4));draw();toast('Task added.','ok')},
pmenu:v=>{const x=proj(v);dlg({title:x.n,body:`<div style="display:grid;gap:4px;margin-top:8px"><button class="linkrow" data-act="toast:Rename opens inline.">${ic('edit')}<span class="main"><b>Edit details</b></span></button><button class="linkrow" data-act="toast:Duplicated as a template.:ok">${ic('copy')}<span class="main"><b>Save as template</b></span></button><button class="linkrow" data-act="parch:${v}">${ic(x.arch?'restore':'archive')}<span class="main"><b>${x.arch?'Restore project':'Archive project'}</b><small>${x.arch?'Brings it back to the sidebar and lists.':'Hides it everywhere except search. Nothing is deleted.'}</small></span></button></div>`,acts:[['Close','noop']]})},
parch:v=>{const x=proj(v);x.arch=!x.arch;toast(x.arch?`“${x.n}” archived. Find it any time with search.`:`“${x.n}” restored.`,'ok');nav(x.arch?'projects/list':`projects/p/${v}/overview`)},
newproj:()=>dlg({title:'New project',body:`<div class="field" style="margin-top:12px"><label for="np">Project name</label><input id="np" placeholder="e.g. Webinar funnel for Nova Yoga"></div><div class="row2"><div class="field"><label for="npc">Client</label><select id="npc"><option>Internal</option><option>Harry Kaye PT</option><option>Mindful Money Co</option></select></div><div class="field"><label for="npl">Lead</label><select id="npl">${Object.keys(PEOPLE).map(k=>`<option value="${k}">${PEOPLE[k][0]}</option>`).join('')}</select></div></div><div class="field"><label for="npt">Start from</label><select id="npt"><option>Blank project</option><option>Client funnel (5 stages)</option><option>Course launch</option><option>Internal improvement</option></select></div>`,acts:[['Cancel','noop'],['Create project','newproj2','primary']]}),
newproj2:()=>{const n=($('#np')?.value||'').trim()||'Untitled project';const id='n'+Date.now();projs().push({id,n,cl:$('#npc').value,lead:$('#npl').value,st:'Planning',pr:0,due:'Dec',c:'#2B63F6',team:[$('#npl').value],purpose:'Add a purpose so everyone knows why this exists.'});TASKS[id]=[];toast('Project created.','ok');nav(`projects/p/${id}/overview`)},
timer:(v,t)=>{const w=$('#tmr');if(TMR){clearInterval(TMR);TMR=null;w.classList.remove('run');t.innerHTML=ic('play',16)+'Resume';toast('Timer paused. Time saved to this task.','ok');return}let s=+(w.dataset.s||0);w.classList.add('run');t.innerHTML=ic('pause',16)+'Pause';TMR=setInterval(()=>{if(!document.body.contains(w)){clearInterval(TMR);TMR=null;return}s++;w.dataset.s=s;$('b',w).textContent=new Date(s*1000).toISOString().slice(11,19)},1000)},
sub:(v,t)=>{const r=t.closest('.row'),d=r.classList.toggle('done');t.setAttribute('aria-checked',d)}
});
document.addEventListener('change',e=>{const s=e.target.dataset.tst;if(s){const[p,i]=s.split('-');TASKS[p][+i].st=e.target.value;toast('Status updated.','ok',1500);if(RT.a==='projects'){const op=$('#drawer').innerHTML;draw();$('#drawer').innerHTML=op;$('#drawer').classList.add('open')}}});
let dragId=null;
document.addEventListener('dragstart',e=>{const c=e.target.closest?.('.kcard');if(c){dragId=c.dataset.id;c.classList.add('dragging');e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragend',e=>{e.target.closest?.('.kcard')?.classList.remove('dragging');$$('.kcol.over').forEach(c=>c.classList.remove('over'))});
document.addEventListener('dragover',e=>{const c=e.target.closest?.('.kcol');if(c&&dragId){e.preventDefault();$$('.kcol.over').forEach(x=>x!==c&&x.classList.remove('over'));c.classList.add('over')}});
document.addEventListener('drop',e=>{const c=e.target.closest?.('.kcol');if(c&&dragId){e.preventDefault();const[p,i]=dragId.split('-');TASKS[p][+i].st=c.dataset.st;dragId=null;draw();toast('Moved to '+TST[c.dataset.st][0]+'.','ok',1500)}});
